"use client";

import { useEffect, useRef, useState, type FormEvent } from "react";
import { ArrowRightLeft, BarChart3, Boxes, Building2, ChevronDown, CircleDollarSign, ClipboardList, CreditCard, KeyRound, LayoutDashboard, LogOut, Menu, Minus, PackageCheck, Plus, Printer, ReceiptText, Search, Settings, ShieldCheck, ShoppingBasket, ShoppingCart, SlidersHorizontal, Store, Trash2, TrendingUp, Users, WalletCards, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

type Product = { id:string | number; name:string; barcode:string; barcodes?:{id:string;barcode:string;isPrimary:boolean}[]; priceHistory?:{oldSalePrice:number;newSalePrice:number;oldCostPrice:number;newCostPrice:number;changedAt:string}[]; sku:string; category:string; location:string; stock:number; min:number; price:number; cost:number };
type SaleItem = { name:string; quantity:number; unitPrice:number; lineTotal:number };
type RecentSale = { id:string; receiptNo:string; total:number; status:"completed"|"returned"; createdAt:string; cashier:string; paymentMethod:string; items:SaleItem[] };
type DashboardData = { today:{total:number;count:number;profit:number};payments:{cash:number;card:number};weekly:{day:string;total:number}[];recent:RecentSale[];shift:null|{id:string;openedAt:string;openingCash:number;cashSales:number;cardSales:number;expectedCash:number}; registerName?:string; branchName?:string; branchAddress?:string; alerts?:{name:string;location:string;stock:number;min:number}[]; suspicious?:{receiptNo:string;kind:string;cashier:string;total:number;createdAt:string}[] };
type PosOrder = { id:string; order_no:string; customerId?:string; customer_name:string; items:{productId:string;quantity:number}[] };
type AuthUser={id:string;fullName:string;role:string;permissions:string[]};
type AuthState={authenticated:boolean;user?:AuthUser;setupRequired?:boolean;users?:{id:string;fullName:string;role:string;hasPin:boolean}[]};

const nav = [
  ["İdarə paneli", LayoutDashboard], ["Satış / POS", ShoppingCart], ["Məhsullar", Boxes], ["Anbar", PackageCheck], ["Sifarişlər", ClipboardList], ["Satınalma", ShoppingBasket], ["Maliyyə", CircleDollarSign], ["İnsan resursları", Users], ["Hesabatlar", BarChart3], ["Nəzarət jurnalı", ShieldCheck], ["Tənzimləmələr", Settings],
] as const;

const money = (value:number) => { const [whole,decimal]=Number(value||0).toFixed(2).split("."); return `${whole.replace(/\B(?=(\d{3})+(?!\d))/g," ")},${decimal} ₼` };

export default function Home() {
  const [auth,setAuth]=useState<AuthState|null>(null);
  const [active,setActive] = useState("İdarə paneli");
  const [mobileNav,setMobileNav] = useState(false);
  const [query,setQuery] = useState("");
  const [productList,setProductList] = useState<Product[]>([]);
  const [dataStatus,setDataStatus] = useState<"loading"|"live"|"offline">("loading");
  const [cart,setCart] = useState<Record<string,number>>({});
  const [notice,setNotice] = useState("");
  const [dashboard,setDashboard] = useState<DashboardData|null>(null);
  const [posOrder,setPosOrder] = useState<PosOrder|null>(null);
  async function loadProducts() {
    setDataStatus("loading");
    fetch("/api/products", { cache: "no-store" })
      .then(async (response): Promise<Product[]> => {
        if (!response.ok) throw new Error("Məhsullar yüklənmədi");
        return response.json() as Promise<Product[]>;
      })
      .then((rows: Product[]) => { setProductList(rows); setDataStatus("live"); })
      .catch(() => { setProductList([]); setDataStatus("offline"); });
  }
  async function loadDashboard(){try{const response=await fetch("/api/dashboard",{cache:"no-store"});if(!response.ok)throw new Error();setDashboard(await response.json() as DashboardData)}catch{setDashboard(null)}}
  async function loadAuth(){try{const response=await fetch("/api/auth",{cache:"no-store"});setAuth(await response.json() as AuthState)}catch{setAuth({authenticated:false,users:[]})}}
  useEffect(() => { void loadAuth(); }, []);
  useEffect(()=>{function report(message:string,detail?:string){void fetch("/api/client-errors",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message,detail})})}function onError(event:ErrorEvent){report(event.message,`${event.filename||""}:${event.lineno||0}`)}function onRejection(event:PromiseRejectionEvent){report(event.reason instanceof Error?event.reason.message:String(event.reason||"Gözlənilməz xəta"),event.reason instanceof Error?event.reason.stack:"")}window.addEventListener("error",onError);window.addEventListener("unhandledrejection",onRejection);return()=>{window.removeEventListener("error",onError);window.removeEventListener("unhandledrejection",onRejection)}},[]);
  useEffect(() => { if(auth?.authenticated){void loadProducts();void loadDashboard()} }, [auth?.authenticated]);
  const filtered = productList.filter(p => `${p.name} ${p.barcode} ${(p.barcodes||[]).map(b=>b.barcode).join(" ")} ${p.sku}`.toLocaleLowerCase("az").includes(query.toLocaleLowerCase("az")));
  const cartRows = productList.filter(p => cart[String(p.id)]);
  const subtotal = cartRows.reduce((sum,p) => sum + p.price * cart[p.id], 0);
  const totalUnits = productList.reduce((sum,p) => sum+p.stock,0);
  function add(product:Product){ const id=String(product.id); setCart(c=>{const current=c[id]||0;if(current>=product.stock){setNotice(`${product.name}: stokda ${product.stock} ədəd var`);return c}setNotice(`${product.name} çekə yazıldı`);return {...c,[id]:current+1}}); window.setTimeout(()=>setNotice(""),1800) }
  function updateCart(productId:string|number,change:number){ const id=String(productId); setCart(c=>{ const next=Math.max(0,(c[id]||0)+change); const copy={...c}; if(!next) delete copy[id]; else copy[id]=next; return copy }) }
  function selectSection(label:string){ setActive(label); setMobileNav(false); setQuery("") }
  if(!auth)return <div className="auth-loading"><Store size={32}/><strong>BirKassa açılır...</strong></div>;
  if(!auth.authenticated||!auth.user)return <LoginScreen state={auth} onAuthenticated={setAuth}/>;
  const allowedNav=nav.filter(([label])=>auth.user?.permissions.includes("*")||auth.user?.permissions.includes(label));
  async function logout(){await fetch("/api/auth",{method:"DELETE"});setAuth(null);setActive("İdarə paneli");await loadAuth()}
  return <main className="app-shell">
    {notice && <div className="toast" role="status">{notice}</div>}
    <aside className={`sidebar ${mobileNav?"sidebar-open":""}`}>
      <div className="brand"><div className="brand-mark"><Store size={22}/></div><div><strong>BirKassa</strong><span>ticarət sistemi</span></div><button className="mobile-close" onClick={()=>setMobileNav(false)} aria-label="Menyunu bağla"><X/></button></div>
      <nav aria-label="Əsas menyu"><p className="nav-label">İŞ SAHƏSİ</p>{allowedNav.map(([label,Icon])=><button key={label} className={active===label?"nav-item active":"nav-item"} onClick={()=>selectSection(label)}><Icon size={19}/><span>{label}</span>{label==="Anbar"&&<em>{dashboard?.alerts?.length||0}</em>}</button>)}</nav>
      <div className="sidebar-footer"><div className="store-status"><span className="status-dot"/><div><strong>{dashboard?.branchName||"Mağaza"}</strong><small>{auth.user.fullName}</small></div></div><button><ChevronDown size={17}/></button></div>
    </aside>
    <section className="workspace">
      <header className="topbar"><button className="menu-button" onClick={()=>setMobileNav(true)} aria-label="Menyunu aç"><Menu/></button><div><p className="eyebrow">{new Date().toLocaleDateString("az-AZ",{day:"2-digit",month:"long",weekday:"long",timeZone:"Asia/Baku"}).toLocaleUpperCase("az")}</p><h1>{active}</h1></div><div className="top-actions"><div className={`db-state ${dataStatus}`}><i/><span>{dataStatus==="live"?"Canlı baza":dataStatus==="loading"?"Baza yoxlanılır":"Baza açılmadı"}</span></div>{(auth.user.role==="admin"||auth.user.role==="cashier"||auth.user.role==="manager")&&<><ShiftControl shift={dashboard?.shift||null} onSaved={loadDashboard}/><Button className="new-sale" onClick={()=>setActive("Satış / POS")} disabled={!dashboard?.shift}><Plus size={18}/> Yeni satış</Button></>}<button className="profile" title={`${auth.user.fullName} · Çıxış`} onClick={logout}><LogOut size={16}/></button></div></header>
      <div className="content">
        {active==="İdarə paneli"&&<><Dashboard totalUnits={totalUnits} productCount={productList.length} data={dashboard} onOpen={setActive} onSaved={async()=>{await Promise.all([loadDashboard(),loadProducts()])}}/><PrintCenter sales={dashboard?.recent||[]} products={productList} storeLine={[dashboard?.branchName,dashboard?.branchAddress].filter(Boolean).join(" · ")||"Mağaza"}/></>} 
        {active==="Satış / POS"&&<PosView query={query} setQuery={setQuery} filtered={filtered} products={productList} cart={cart} cartRows={cartRows} subtotal={subtotal} add={add} updateCart={updateCart} clear={()=>setCart({})} restore={setCart} cashierName={auth.user.fullName} registerName={dashboard?.registerName||"Kassa"} incomingOrder={posOrder} onOrderLoaded={()=>setPosOrder(null)} onCompleted={async()=>{setCart({});setPosOrder(null);await Promise.all([loadProducts(),loadDashboard()])}}/>} 
        {(active==="Məhsullar"||active==="Anbar")&&<><InventoryView products={filtered} query={query} setQuery={setQuery} mode={active} onCreated={loadProducts}/>{active==="Anbar"&&<div className="inventory-count-launch"><InventoryCountDialog products={productList} onSaved={loadProducts}/></div>}</>} 
        {active==="Sifarişlər"&&<OrdersView products={productList} onOpenAtPos={(order)=>{setPosOrder(order);setActive("Satış / POS")}}/>}{active==="Satınalma"&&<PurchasingView products={productList} onStockChanged={loadProducts}/>} {active==="Maliyyə"&&<FinanceView/>}{active==="İnsan resursları"&&<HrView/>}{active==="Hesabatlar"&&<ReportsView/>}{active==="Nəzarət jurnalı"&&<AuditView role={auth.user.role}/>}{active==="Tənzimləmələr"&&<SettingsView/>}
      </div>
    </section>
  </main>
}

function ShiftControl({shift,onSaved}:{shift:DashboardData["shift"];onSaved:()=>Promise<void>}){
  const [open,setOpen]=useState(false),[saving,setSaving]=useState(false),[message,setMessage]=useState(""),[result,setResult]=useState<{expectedCash:number;actualCash:number;difference:number}|null>(null);
  async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();setSaving(true);setMessage("");setResult(null);const form=new FormData(event.currentTarget);const action=shift?"close":"open";try{const response=await fetch("/api/shifts",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action,...Object.fromEntries(form)})});const data=await response.json() as {error?:string;expectedCash?:number;actualCash?:number;difference?:number};if(!response.ok){setMessage(data.error||"Növbə əməliyyatı tamamlanmadı");return}if(action==="close")setResult({expectedCash:data.expectedCash||0,actualCash:data.actualCash||0,difference:data.difference||0});else{setMessage("Kassa növbəsi açıldı");setOpen(false)}await onSaved()}catch{setMessage("Serverlə əlaqə qurulmadı")}finally{setSaving(false)}}
  const time=shift?new Date(shift.openedAt).toLocaleTimeString("az-AZ",{hour:"2-digit",minute:"2-digit",timeZone:"Asia/Baku"}):"";
  return <Dialog open={open} onOpenChange={value=>{setOpen(value);if(!value){setMessage("");setResult(null)}}}><DialogTrigger asChild><button className={`shift shift-trigger ${shift?"open":"closed"}`}><span>{shift?"Növbə açıqdır":"Növbə bağlıdır"}</span><strong>{shift?`${time}-dən`:"Açmaq üçün basın"}</strong></button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>{shift?"Kassa növbəsini bağla":"Kassa növbəsini aç"}</DialogTitle><DialogDescription>{shift?"Kassadakı faktiki nağdı sayın. Sistem gözlənilən məbləğlə fərqi hesablayacaq.":"Kassada növbəyə başladığınız nağd məbləği yazın."}</DialogDescription></DialogHeader>{result?<div className="shift-result"><div><span>Gözlənilən nağd</span><strong>{money(result.expectedCash)}</strong></div><div><span>Faktiki nağd</span><strong>{money(result.actualCash)}</strong></div><div className={result.difference===0?"balanced":result.difference>0?"over":"short"}><span>Kassa fərqi</span><strong>{result.difference>0?"+":""}{money(result.difference)}</strong></div><Button onClick={()=>setOpen(false)}>Bağla</Button></div>:<form className="product-form" onSubmit={submit}>{shift&&<div className="shift-summary"><div><span>Başlanğıc pul</span><b>{money(shift.openingCash)}</b></div><div><span>Nağd satış</span><b>{money(shift.cashSales)}</b></div><div><span>Gözlənilən</span><b>{money(shift.expectedCash)}</b></div></div>}<label>{shift?"Faktiki nağd":"Başlanğıc nağd"}<Input name={shift?"actualCash":"openingCash"} type="number" min="0" step="0.01" required autoFocus/></label>{message&&<p className={message.includes("açıldı")?"form-success":"form-error"}>{message}</p>}<DialogFooter><Button type="button" variant="outline" onClick={()=>setOpen(false)}>Ləğv et</Button><Button type="submit" disabled={saving} variant={shift?"destructive":"default"}>{saving?"Saxlanılır...":shift?"Növbəni bağla":"Növbəni aç"}</Button></DialogFooter></form>}</DialogContent></Dialog>}

function Dashboard({totalUnits,productCount,data,onOpen,onSaved}:{totalUnits:number;productCount:number;data:DashboardData|null;onOpen:(value:string)=>void;onSaved:()=>Promise<void>}){const [selected,setSelected]=useState<RecentSale|null>(null),[returnMode,setReturnMode]=useState(false),[returnReason,setReturnReason]=useState(""),[managerPin,setManagerPin]=useState(""),[returning,setReturning]=useState(false),[returnError,setReturnError]=useState("");const average=data?.today.count?data.today.total/data.today.count:0;const max=Math.max(...(data?.weekly.map(x=>x.total)||[0]),1);const weeklyTotal=data?.weekly.reduce((sum,x)=>sum+x.total,0)||0;const paymentLabel=(value:string)=>value==="cash"?"Nağd":value==="card"?"Kart":value||"—";async function returnSale(){if(!selected||returnReason.trim().length<3){setReturnError("Qaytarma səbəbini yazın");return}setReturning(true);setReturnError("");try{const response=await fetch("/api/returns",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({saleId:selected.id,reason:returnReason,managerPin})});const result=await response.json() as {error?:string};if(!response.ok){setReturnError(result.error||"Qaytarma tamamlanmadı");return}setSelected(null);setReturnMode(false);setReturnReason("");setManagerPin("");await onSaved()}catch{setReturnError("Serverlə əlaqə qurulmadı")}finally{setReturning(false)}}return <><section className="metric-grid"><Metric icon={WalletCards} label="Bu gün satış" value={money(data?.today.total||0)} detail="Canlı POS satışları" positive/><Metric icon={ReceiptText} label="Çek sayı" value={String(data?.today.count||0)} detail={`Orta çek ${money(average)}`}/><Metric icon={Boxes} label="Ümumi qalıq" value={`${totalUnits} ədəd`} detail={`${productCount} aktiv məhsul`}/><Metric icon={TrendingUp} label="Təxmini qazanc" value={money(data?.today.profit||0)} detail="Satış − alış dəyəri" positive/></section><section className="dashboard-grid">
  <div className="panel sales-chart"><div className="panel-head"><div><span>SON 7 GÜN</span><h2>Satış dinamikası</h2></div><Badge variant="outline">Canlı</Badge></div><div className="chart-summary"><strong>{money(weeklyTotal)}</strong><span>7 günlük ümumi satış</span></div><div className="bars" aria-label="Həftəlik satış diaqramı">{(data?.weekly||[]).map((entry,index)=><div key={entry.day}><span style={{height:`${Math.max(4,entry.total/max*100)}%`}}/><small>{["B.e","Ç.a","Ç","C.a","C","Ş","B"][new Date(entry.day).getDay()===0?6:new Date(entry.day).getDay()-1]||index+1}</small></div>)}</div></div>
  <div className="panel alerts"><div className="panel-head"><div><span>DİQQƏT TƏLƏB EDİR</span><h2>Anbar xəbərdarlıqları</h2></div><button onClick={()=>onOpen("Anbar")}>Hamısı</button></div>{data?.alerts?.length?data.alerts.map(alert=><AlertRow key={alert.name} name={alert.name} meta={alert.location} value={`${alert.stock} / ${alert.min}`} danger={alert.stock<=alert.min}/>):<p className="empty-table">Aşağı stok yoxdur</p>}{!!data?.suspicious?.length&&<div className="suspicious-list"><strong>Şübhəli əməliyyatlar</strong>{data.suspicious.map(item=><p key={`${item.kind}-${item.receiptNo}`}>{item.kind==="return"?"Qaytarma":"Yüksək endirim"} · {item.receiptNo} · {item.cashier}</p>)}</div>}</div>
  <div className="panel recent"><div className="panel-head"><div><span>CANLI AXIN</span><h2>Son satışlar</h2></div><span className="live-pill"><i/> Bazadan</span></div><div className="table-wrap"><table><thead><tr><th>Çek</th><th>Saat</th><th>Kassir</th><th>Ödəniş</th><th className="right">Məbləğ</th></tr></thead><tbody>{data?.recent.length?data.recent.map(sale=><tr key={sale.id} className="clickable-row" onClick={()=>{setSelected(sale);setReturnMode(false);setReturnError("")}}><td><strong>{sale.receiptNo}</strong>{sale.status==="returned"&&<Badge variant="destructive" className="return-badge">Qaytarılıb</Badge>}</td><td>{new Date(sale.createdAt).toLocaleTimeString("az-AZ",{hour:"2-digit",minute:"2-digit",timeZone:"Asia/Baku"})}</td><td>{sale.cashier}</td><td><Badge variant="secondary">{paymentLabel(sale.paymentMethod)}</Badge></td><td className="right">{money(sale.total)}</td></tr>):<tr><td colSpan={5} className="empty-table">Hələ satış yoxdur</td></tr>}</tbody></table></div></div>
  <div className="panel shift-card"><div className="panel-head"><div><span>AKTİV NÖVBƏ</span><h2>Kassa vəziyyəti</h2></div><span className="live-pill"><i/> {data?.shift?"Açıq":"Bağlı"}</span></div><div className="cash-total"><span>Sistemdə gözlənilən nağd</span><strong>{money(data?.shift?.expectedCash||0)}</strong></div><div className="cash-split"><span><small>Nağd satış</small><b>{money(data?.shift?.cashSales||0)}</b></span><span><small>Kart satışı</small><b>{money(data?.shift?.cardSales||0)}</b></span></div><div className="shift-card-action"><ShiftControl shift={data?.shift||null} onSaved={onSaved}/></div></div>
  </section><Dialog open={Boolean(selected)} onOpenChange={open=>{if(!open){setSelected(null);setReturnMode(false);setReturnReason("");setReturnError("")}}}><DialogContent><DialogHeader><DialogTitle>Çek {selected?.receiptNo} {selected?.status==="returned"&&<Badge variant="destructive">Qaytarılıb</Badge>}</DialogTitle><DialogDescription>{selected&&`${new Date(selected.createdAt).toLocaleString("az-AZ",{timeZone:"Asia/Baku"})} · ${selected.cashier}`}</DialogDescription></DialogHeader><div className="receipt-detail">{selected?.items.map((item,index)=><div key={`${item.name}-${index}`}><span><strong>{item.name}</strong><small>{item.quantity} × {money(item.unitPrice)}</small></span><b>{money(item.lineTotal)}</b></div>)}</div><div className="receipt-detail-total"><span>Ödəniş: {paymentLabel(selected?.paymentMethod||"")}</span><strong>{money(selected?.total||0)}</strong></div>{returnMode&&selected?.status==="completed"&&<div className="return-confirm"><strong>Satışı tam qaytarmaq istəyirsiniz?</strong><span>Məhsullar anbara geri əlavə ediləcək.</span><Input value={returnReason} onChange={e=>setReturnReason(e.target.value)} placeholder="Qaytarma səbəbi" autoFocus/><Input value={managerPin} onChange={e=>setManagerPin(e.target.value)} inputMode="numeric" maxLength={6} placeholder="Rəhbər PIN-i" type="password"/>{returnError&&<p className="form-error">{returnError}</p>}</div>}<DialogFooter><Button variant="outline" onClick={()=>{setSelected(null);setReturnMode(false)}}>Bağla</Button>{selected?.status==="completed"&&(returnMode?<Button variant="destructive" disabled={returning} onClick={returnSale}>{returning?"Qaytarılır...":"Qaytarmanı təsdiqlə"}</Button>:<Button variant="destructive" onClick={()=>setReturnMode(true)}>Satışı qaytar</Button>)}</DialogFooter></DialogContent></Dialog></>}

function Metric({icon:Icon,label,value,detail,positive}:{icon:typeof WalletCards;label:string;value:string;detail:string;positive?:boolean}){return <div className="metric"><div className="metric-top"><span>{label}</span><i><Icon size={19}/></i></div><strong>{value}</strong><small className={positive?"positive":""}>{detail}</small></div>}
function AlertRow({name,meta,value,danger}:{name:string;meta:string;value:string;danger?:boolean}){return <div className="alert-row"><div className={danger?"stock-icon danger":"stock-icon"}><Boxes size={18}/></div><div><strong>{name}</strong><small>{meta}</small></div><span className={danger?"danger-text":""}>{value}</span></div>}

function ThermalReceipt({sale,paymentLabel,storeLine}:{sale:RecentSale|null;paymentLabel:(value:string)=>string;storeLine:string}){if(!sale)return null;return <section className="print-sheet thermal-receipt"><header><strong>BirKassa</strong><span>{storeLine}</span><span>Satış çeki {sale.receiptNo}</span></header><div className="print-meta"><span>{new Date(sale.createdAt).toLocaleString("az-AZ",{timeZone:"Asia/Baku"})}</span><span>Kassir: {sale.cashier}</span></div><div className="print-lines">{sale.items.map((item,index)=><div key={index}><span>{item.name}<small>{item.quantity} × {money(item.unitPrice)}</small></span><b>{money(item.lineTotal)}</b></div>)}</div><div className="print-total"><span>YEKUN</span><strong>{money(sale.total)}</strong></div><div className="print-payment">Ödəniş: {paymentLabel(sale.paymentMethod)}</div><footer>Alış-verişiniz üçün təşəkkür edirik</footer></section>}

function BarcodeGraphic({value}:{value:string}){const L=["0001101","0011001","0010011","0111101","0100011","0110001","0101111","0111011","0110111","0001011"],G=["0100111","0110011","0011011","0100001","0011101","0111001","0000101","0010001","0001001","0010111"],R=["1110010","1100110","1101100","1000010","1011100","1001110","1010000","1000100","1001000","1110100"],parity=["LLLLLL","LLGLGG","LLGGLG","LLGGGL","LGLLGG","LGGLLG","LGGGLL","LGLGLG","LGLGGL","LGGLGL"];let digits=value.replace(/\D/g,"");if(digits.length===12){const sum=digits.split("").reduce((s,d,i)=>s+Number(d)*(i%2===0?1:3),0);digits+=String((10-sum%10)%10)}if(digits.length!==13)return <div className="barcode-fallback">{value||"Barkod yoxdur"}</div>;const left=digits.slice(1,7).split("").map((d,i)=>(parity[Number(digits[0])][i]==="L"?L:G)[Number(d)]).join(""),right=digits.slice(7).split("").map(d=>R[Number(d)]).join(""),bits=`101${left}01010${right}101`;return <svg className="ean-barcode" viewBox="0 0 95 60" role="img" aria-label={`EAN-13 ${digits}`}>{bits.split("").map((bit,i)=>bit==="1"?<rect key={i} x={i} y="0" width="1" height={(i<3||(i>=45&&i<50)||i>=92)?50:44}/>:null)}<text x="47.5" y="58" textAnchor="middle" fontSize="7">{digits}</text></svg>}

function BarcodeLabel({product}:{product:Product|null}){if(!product)return null;return <section className="print-sheet barcode-label"><strong>BirKassa</strong><h2>{product.name}</h2><BarcodeGraphic value={product.barcode}/><div><span>{product.sku}</span><b>{money(product.price)}</b></div></section>}

function PrintCenter({sales,products,storeLine}:{sales:RecentSale[];products:Product[];storeLine:string}){const [open,setOpen]=useState(false),[mode,setMode]=useState<"receipt"|"barcode">("receipt"),[saleId,setSaleId]=useState(""),[productId,setProductId]=useState("");const sale=sales.find(x=>x.id===saleId)||null,product=products.find(x=>String(x.id)===productId)||null;const paymentLabel=(value:string)=>value==="cash"?"Nağd":value==="card"?"Kart":value.includes("cash")&&value.includes("card")?"Qarışıq":value||"—";return <div className="print-center-launch"><Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button variant="outline"><Printer size={16}/>Çap mərkəzi</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Çap mərkəzi</DialogTitle><DialogDescription>Əvvəlki çeki yenidən çap edin və ya məhsul üçün barkod etiketi hazırlayın.</DialogDescription></DialogHeader><div className="print-mode"><button className={mode==="receipt"?"selected":""} onClick={()=>setMode("receipt")}>Termal çek</button><button className={mode==="barcode"?"selected":""} onClick={()=>setMode("barcode")}>Barkod etiketi</button></div>{mode==="receipt"?<label className="dialog-label">Satış çeki<Select value={saleId} onValueChange={setSaleId}><SelectTrigger className="w-full"><SelectValue placeholder="Çek seçin"/></SelectTrigger><SelectContent>{sales.map(row=><SelectItem key={row.id} value={row.id}>{row.receiptNo} · {money(row.total)} · {new Date(row.createdAt).toLocaleString("az-AZ",{timeZone:"Asia/Baku"})}</SelectItem>)}</SelectContent></Select></label>:<label className="dialog-label">Məhsul<Select value={productId} onValueChange={setProductId}><SelectTrigger className="w-full"><SelectValue placeholder="Məhsul seçin"/></SelectTrigger><SelectContent>{products.map(row=><SelectItem key={row.id} value={String(row.id)}>{row.name} · {row.barcode}</SelectItem>)}</SelectContent></Select></label>}<div className="print-preview">{mode==="receipt"?(sale?<ThermalReceipt sale={sale} paymentLabel={paymentLabel} storeLine={storeLine}/>:<span>Çap görünüşü üçün çek seçin</span>):product?<BarcodeLabel product={product}/>:<span>Etiket üçün məhsul seçin</span>}</div><DialogFooter><Button type="button" variant="outline" onClick={()=>setOpen(false)}>Bağla</Button><Button type="button" disabled={mode==="receipt"?!sale:!product} onClick={()=>window.print()}><Printer size={16}/>Çap et</Button></DialogFooter></DialogContent></Dialog></div>}

