type CountHistory={id:string;count_no:string;created_at:string;note?:string;full_name:string;product_name:string;systemQuantity:number;actualQuantity:number;difference:number};
function InventoryCountDialog({products,onSaved}:{products:Product[];onSaved:()=>Promise<void>}){const [open,setOpen]=useState(false),[productId,setProductId]=useState(""),[actual,setActual]=useState(""),[lines,setLines]=useState<{productId:string;name:string;system:number;actual:number}[]>([]),[history,setHistory]=useState<CountHistory[]>([]),[saving,setSaving]=useState(false),[message,setMessage]=useState(""),[note,setNote]=useState("");const selected=products.find(p=>String(p.id)===productId),difference=selected&&actual!==""?Number(actual)-selected.stock:null;async function load(){const response=await fetch("/api/inventory-counts",{cache:"no-store"});if(response.ok)setHistory(await response.json() as CountHistory[])}useEffect(()=>{if(open)void load()},[open]);function addLine(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!selected||actual===""){setMessage("Məhsul və faktiki sayı yazın");return}setLines(current=>[...current.filter(line=>line.productId!==String(selected.id)),{productId:String(selected.id),name:selected.name,system:selected.stock,actual:Number(actual)}]);setProductId("");setActual("");setMessage("")}async function applyCount(note:string){if(!lines.length){setMessage("Sayım sənədinə sətir əlavə edin");return}setSaving(true);setMessage("");const response=await fetch("/api/inventory-counts",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({apply:true,note,items:lines.map(line=>({productId:line.productId,actualQuantity:line.actual}))})});const result=await response.json() as {error?:string;countNo?:string;lines?:{difference:number}[]};if(response.ok){const difference=result.lines?.reduce((sum,line)=>sum+Number(line.difference),0)||0;setMessage(`${result.countNo} təsdiqləndi və stoka yazıldı · fərq ${difference>0?"+":""}${difference}`);await Promise.all([load(),onSaved()]);setLines([]);setNote("");setProductId("");setActual("")}else setMessage(result.error||"Sayım saxlanmadı");setSaving(false)}return <Dialog open={open} onOpenChange={value=>{setOpen(value);setMessage("")}}><DialogTrigger asChild><Button><ClipboardList size={16}/>Inventar sayımı</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Əsas anbar inventar sayımı</DialogTitle><DialogDescription>Faktiki sayı daxil edin, sətirləri sənədə yığın, sonra fərqi təsdiqləyin.</DialogDescription></DialogHeader><form className="product-form" onSubmit={addLine}><label>Məhsul<Select value={productId} onValueChange={value=>{setProductId(value);setActual("")}}><SelectTrigger className="w-full"><SelectValue placeholder="Məhsul seçin"/></SelectTrigger><SelectContent>{products.map(p=><SelectItem key={p.id} value={String(p.id)}>{p.name} · sistemdə {p.stock}</SelectItem>)}</SelectContent></Select></label>{selected&&<div className="count-preview"><div><span>Sistem qalığı</span><strong>{selected.stock}</strong></div><div><span>Faktiki say</span><strong>{actual===""?"—":actual}</strong></div><div className={difference===0?"balanced":Number(difference)>0?"over":"short"}><span>Fərq</span><strong>{difference===null?"—":`${difference>0?"+":""}${difference}`}</strong></div></div>}<label>Faktiki say<Input name="actualQuantity" type="number" min="0" step="0.001" value={actual} onChange={e=>setActual(e.target.value)} required/></label><label>Sayım qeydi<Input name="note" value={note} onChange={e=>setNote(e.target.value)} placeholder="Sayım səbəbi və ya komissiya qeydi"/></label>{message&&<p className={message.includes("tamamlandı")?"form-success":"form-error"}>{message}</p>}<DialogFooter><Button type="submit" variant="outline" disabled={!productId||actual===""}>Sətr əlavə et</Button></DialogFooter></form>{lines.length>0&&<div className="count-history"><strong>Sayım sənədi</strong>{lines.map(line=><div key={line.productId}><span>{line.name}</span><b>{line.system} → {line.actual} ({line.actual-line.system})</b></div>)}<Button disabled={saving} onClick={()=>applyCount(note)}>{saving?"Tətbiq edilir...":"Fərqi təsdiqlə və stoka yaz"}</Button></div>}{history.length>0&&<div className="count-history"><strong>Son sayımlar</strong>{history.slice(0,5).map(row=><div key={row.id}><span>{row.count_no} · {row.product_name}</span><b className={row.difference===0?"money-in":"money-out"}>{row.systemQuantity} → {row.actualQuantity} ({row.difference})</b></div>)}</div>}</DialogContent></Dialog>}

