  async function createOrder(event:FormEvent<HTMLFormElement>){event.preventDefault();setSaving(true);setMessage("");const form=new FormData(event.currentTarget);const response=await fetch("/api/purchase-orders",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.fromEntries(form))});const result=await response.json() as {error?:string};if(response.ok){await load();setOrderOpen(false)}else setMessage(result.error||"Sifariş saxlanmadı");setSaving(false)}
